    #[test]
    fn script_of_matches_scripts_txt_for_every_code_point() {
        let mut value: Vec<Option<&str>> = vec![None; LIMIT];
        for fields in SCRIPTS.lines().filter_map(fields) {
            for cp in span(fields[0]) {
                value[cp as usize] = Some(fields[1]);
            }
        }
        for c in chars() {
            let expected = value[c as usize]
                .and_then(|name| {
                    ALL_SCRIPTS
                        .iter()
                        .copied()
                        .find(|&script| script != Script::Other && script.as_str() == name)
                })
                .unwrap_or(Script::Other);
            assert_eq!(script_of(c), expected, "U+{:04X}", u32::from(c));
        }
    }

    #[test]
    fn is_han_agrees_with_script_of() {
        for c in chars() {
            assert_eq!(
                is_han(c),
                script_of(c) == Script::Han,
                "U+{:04X}",
                u32::from(c)
            );
        }
    }

    #[test]
    fn standardized_variants_are_pairs_of_base_then_selector() {
        for (base, selector) in [(0x0030, 0xFE00), (0x1820, 0x180B), (0x349E, 0xFE00)] {
            assert!(
                is_standardized_variant(ch(base), ch(selector)),
                "U+{base:04X} U+{selector:04X}"
            );
        }
        for (base, selector) in [
            (0xFE00, 0x0030),
            (0x0041, 0xFE00),
            (0x2139, 0xFE0F),
            (0x2764, 0xFE0F),
            (0x4E00, 0xE0100),
            (0x1820, 0x180F),
        ] {
            assert!(
                !is_standardized_variant(ch(base), ch(selector)),
                "U+{base:04X} U+{selector:04X}"
            );
        }
    }

    fn chars_of(cps: &[u32]) -> Vec<char> {
        cps.iter().map(|&cp| ch(cp)).collect()
    }

    #[test]
    fn decompositions_are_expanded_all_the_way_down() {
        let expected: [(u32, &[u32]); 11] = [
            (0x00C5, &[0x0041, 0x030A]),
            (0x212B, &[0x0041, 0x030A]),
            (0x1E9B, &[0x0073, 0x0307]),
            (0x1E69, &[0x0073, 0x0323, 0x0307]),
            (0x01C4, &[0x0044, 0x005A, 0x030C]),
            (0xFB01, &[0x0066, 0x0069]),
            (0x2139, &[0x0069]),
            (0x00A0, &[0x0020]),
            (0xFFA0, &[0x1160]),
            (0x1F213, &[0x30C6, 0x3099]),
            (0x00BD, &[0x0031, 0x2044, 0x0032]),
        ];
        for (cp, mapping) in expected {
            assert_eq!(
                decomposition(ch(cp)),
                Some(&chars_of(mapping)[..]),
                "U+{cp:04X}"
            );
        }
        let fdfa = decomposition('\u{FDFA}').expect("U+FDFA decomposes");
        assert_eq!(fdfa.len(), 18);
        assert_eq!(fdfa[..4], chars_of(&[0x0635, 0x0644, 0x0649, 0x0020])[..]);
        for cp in [0x0041, 0x0020, 0x4E00] {
            assert_eq!(decomposition(ch(cp)), None, "U+{cp:04X}");
        }
    }

    /// Assert-only: the same fact is the build-time gate G6, and no
    /// mutation of the committed data can paint it red without
    /// fabricating UCD lines.
    #[test]
    fn hangul_is_left_to_arithmetic() {
        assert_eq!(decomposition('\u{AC00}'), None);
        assert_eq!(decomposition('\u{D7A3}'), None);
        assert_eq!(compose('\u{1100}', '\u{1161}'), None);
        assert_eq!(compose('\u{AC00}', '\u{11A8}'), None);
        for c in chars() {
            if let Some(expansion) = decomposition(c) {
                assert!(
                    !expansion
                        .iter()
                        .any(|&part| ('\u{AC00}'..='\u{D7A3}').contains(&part)),
                    "the decomposition of U+{:04X} holds a Hangul syllable",
                    u32::from(c)
                );
            }
        }
    }

