    #[test]
    fn primary_composites_compose_and_excluded_ones_do_not() {
        for (first, second, composite) in [
            (0x0041, 0x030A, 0x00C5),
            (0x0065, 0x0301, 0x00E9),
            (0x0049, 0x0307, 0x0130),
            (0x03B9, 0x0308, 0x03CA),
            (0x0B47, 0x0B3E, 0x0B4B),
            (0x30C6, 0x3099, 0x30C7),
        ] {
            assert_eq!(
                compose(ch(first), ch(second)),
                Some(ch(composite)),
                "U+{first:04X} U+{second:04X}"
            );
        }
        for (first, second) in [
            (0x0915, 0x093C),
            (0x2ADD, 0x0338),
            (0x0F71, 0x0F72),
            (0x0041, 0x0041),
        ] {
            assert_eq!(
                compose(ch(first), ch(second)),
                None,
                "U+{first:04X} U+{second:04X}"
            );
        }
    }

    #[test]
    fn composition_is_every_canonical_pair_minus_the_exclusions() {
        let excluded = listed(DERIVED_NORMALIZATION, "Full_Composition_Exclusion");
        let mut pairs = std::collections::BTreeMap::new();
        for line in UNICODE_DATA.lines() {
            let fields: Vec<&str> = line.split(';').collect();
            let mapping = fields[5];
            if mapping.is_empty() || mapping.starts_with('<') {
                continue;
            }
            let parts: Vec<u32> = mapping.split(' ').map(hex).collect();
            if let [first, second] = parts[..] {
                pairs.insert(hex(fields[0]), (first, second));
            }
        }
        for (&composite, &(first, second)) in &pairs {
            let expected = (!excluded[composite as usize]).then(|| ch(composite));
            assert_eq!(
                compose(ch(first), ch(second)),
                expected,
                "U+{composite:04X}"
            );
        }
        for &((first, second), composite) in COMPOSITION {
            let composite = u32::from(composite);
            assert_eq!(
                pairs.get(&composite),
                Some(&(first, second)),
                "U+{composite:04X}"
            );
            assert!(
                !excluded[composite as usize],
                "U+{composite:04X} is excluded"
            );
        }
    }

