    #[test]
    fn the_reverse_index_holds_every_twin_and_the_prototype() {
        let expected: [(u32, Script, &[u32]); 10] = [
            (0x0061, Script::Cyrillic, &[0x0430]),
            (0x0061, Script::Greek, &[0x03B1]),
            (
                0x0061,
                Script::Latin,
                &[0x0061, 0x0251, 0xAB64, 0xFF41, 0x1DF5A],
            ),
            (0x006F, Script::Greek, &[0x03BF, 0x03C3]),
            (0x006F, Script::Cyrillic, &[0x043E, 0x1C82]),
            (0x0063, Script::Greek, &[0x03F2]),
            (0x0033, Script::Cyrillic, &[0x0417, 0x04E0]),
            (0x006F, Script::Hangul, &[]),
            (0x0061, Script::Han, &[]),
            (0x0436, Script::Cyrillic, &[]),
        ];
        for (target, script, members) in expected {
            assert_eq!(
                confusables_with(ch(target), script),
                &chars_of(members)[..],
                "U+{target:04X} in {script:?}"
            );
        }
    }

    #[test]
    fn every_reverse_entry_maps_back_to_its_target() {
        let mut seen = std::collections::BTreeSet::new();
        for &(target, script, members) in CONFUSABLE_REVERSE {
            assert!(
                matches!(script, Script::Latin | Script::Cyrillic | Script::Greek),
                "U+{target:04X} in {script:?}"
            );
            assert!(
                seen.insert((target, script.as_str())),
                "U+{target:04X} in {script:?} twice"
            );
            assert!(!members.is_empty(), "U+{target:04X} in {script:?} is empty");
            assert!(
                members.windows(2).all(|pair| pair[0] < pair[1]),
                "ascending"
            );
            for &member in members {
                let at = format!("U+{:04X} under U+{target:04X}", u32::from(member));
                assert_eq!(
                    u32::from(confusable_target(member).unwrap_or(member)),
                    target,
                    "{at}"
                );
                assert_eq!(script_of(member), script, "{at}");
                assert!(is_letter(member), "{at}");
            }
        }
    }
